from pathlib import Path

path = Path('/home/ubuntu/marketing-agent-dashboard/frontend/index.html')
s = path.read_text()
start = s.find('function exportPricingImage(){')
end = s.find('\nlet pricePhotoData', start)
if start < 0 or end < 0:
    raise SystemExit('PNG function bounds not found')

new_fn = r'''function exportPricingImage(){if(!latestPricing){alert('Calcule uma precificação antes de exportar.');return}const p=latestPricing,w=1400,h=1060,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');if(!ctx){showExportStatus('Seu navegador não conseguiu preparar a imagem.');return}const rounded=(x,y,width,height,r,fill,stroke)=>{ctx.beginPath();ctx.roundRect(x,y,width,height,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}};const text=(value,x,y,maxWidth,lineHeight,font,color)=>{ctx.font=font;ctx.fillStyle=color;String(value||'').split('\n').forEach((line,index)=>{const words=line.split(' ');let current='';let row=0;words.forEach(word=>{const next=current?current+' '+word:word;if(ctx.measureText(next).width>maxWidth&&current){ctx.fillText(current,x,y+(index+row)*lineHeight);current=word;row++}else current=next});if(current)ctx.fillText(current,x,y+(index+row)*lineHeight)})};ctx.fillStyle='#080b13';ctx.fillRect(0,0,w,h);rounded(40,40,1320,980,26,'#101827','#283552');ctx.fillStyle='rgba(109,61,245,.13)';ctx.beginPath();ctx.arc(1240,115,180,0,Math.PI*2);ctx.fill();text('AGENTE DE MARKETING DIGITAL',90,105,600,24,'700 19px Arial','#a990ff');text('Orçamento de '+p.name,90,155,1160,45,'700 38px Arial','#f4f1ff');text('Estimativa revisável · '+p.date,90,190,1160,24,'400 17px Arial','#96a2ba');const cards=[['MÍNIMO',p.minimum,'#22c8de'],['RECOMENDADO',p.suggested,'#a990ff'],['PREMIUM',p.premium,'#ef78c8']];cards.forEach((card,index)=>{const x=90+index*410;rounded(x,235,370,142,16,'#151f32',card[2]);text(card[0],x+25,272,320,20,'700 15px Arial','#9aa8c2');text(money(card[1]),x+25,325,320,38,'700 32px Arial','#ffffff')});text('MEMÓRIA DE CÁLCULO',90,438,560,22,'700 16px Arial','#a990ff');const rows=[`Mão de obra: ${p.hours} h × ${money(p.rate)} = ${money(p.labor)}`,`Materiais e insumos: ${money(p.materials)}`,`Embalagem e frete: ${money(p.packaging)}`,`Custos indiretos: ${money(p.overhead)}`,`Custo base: ${money(p.base)}`,`Taxas: ${p.feesPct.toFixed(1)}% · Margem: ${p.marginPct.toFixed(1)}%`];rows.forEach((row,index)=>text(row,90,480+index*34,590,24,'400 18px Arial','#c3ccdc'));text('ANÁLISE VISUAL ASSISTIDA',760,438,560,22,'700 16px Arial','#a990ff');text(p.visual||'Nenhuma observação visual disponível.',760,480,540,28,'400 16px Arial','#c3ccdc');rounded(90,745,1220,150,14,'#0d3440','#22c8de');text('ESTIMATIVA REVISÁVEL',120,790,1120,24,'700 17px Arial','#55e1ee');text('Revise custos, posicionamento e negociação antes de enviar ao cliente.',120,830,1120,24,'400 18px Arial','#d5f7fa');text('Nenhuma publicação ou ação externa é executada automaticamente.',120,865,1120,24,'400 18px Arial','#d5f7fa');const a=document.createElement('a');a.download=`orcamento-${(p.name||'produto').toLowerCase().replace(/[^a-z0-9]+/gi,'-')}.png`;a.href=canvas.toDataURL('image/png');a.style.display='none';document.body.appendChild(a);a.click();showExportStatus('Imagem PNG gerada e enviada para download.');setTimeout(()=>a.remove(),1000)}'''
s = s[:start] + new_fn + s[end:]
path.write_text(s)
print('PNG export replaced with direct canvas renderer')
